import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import Footer from "@/components/Footer.vue";
import Logo from "@/components/Logo.vue";
export default {
  name: "ClientLogin",
  components: {
    Footer,
    Logo
  },
  props: {
    // 页面标题
    title: {
      type: String,
      required: true
    },
    // 输入字段配置
    // 格式: [{ key: 'username', label: '用户名', placeholder: '请输入用户名', type: 'text', showPassword: false }]
    fields: {
      type: Array,
      required: true
    },
    // 提交按钮文本
    submitText: {
      type: String,
      default: "登录"
    },
    // 背景图配置键名
    backgroundKey: {
      type: String,
      required: true
    },
    // 提交功能
    submitFunc: {
      type: Function,
      required: true
    }
  },
  data() {
    return {
      formData: {},
      isLoading: false
    };
  },
  mounted() {
    // 初始化表单数据
    this.initFormData();
    this.isLoading = false;
  },
  methods: {
    initFormData() {
      // 根据字段配置初始化表单数据
      const newFormData = {};
      this.fields.forEach(field => {
        newFormData[field.key] = "";
      });
      this.formData = newFormData;
    },
    async handleSubmit() {
      // 触发父组件的提交事件，传递表单数据
      for (const key in this.formData) {
        if (this.formData[key] === "") {
          this.$message.error("请填写所有字段");
          this.isLoading = false;
          return;
        }
      }
      this.isLoading = true;
      await this.submitFunc({
        ...this.formData
      });
      this.isLoading = false;
    }
  }
};